const nums = [10, 9, 1, 100];

console.log(`Default: ${nums.toSorted().join(", ")}`);
console.log(`Ascending: ${nums.toSorted((a, b) => a - b).join(", ")}`);
console.log(`Original: ${nums.join(", ")}`);
nums.sort((a, b) => b - a);
console.log(`Descending in place: ${nums.join(", ")}`);

const fruits = ["banana", "kiwi", "apple", "fig", "cherry"];
const abc = fruits.toSorted((a, b) => a.localeCompare(b));
const byLength = fruits.toSorted((a, b) => a.length - b.length || a.localeCompare(b));
console.log(`Alphabetical: ${abc.join(" ")}`);
console.log(`By length: ${byLength.join(" ")}`);

